async function render(){const hr=me.role==='HR'||me.role==='ADMIN';if(!hr&&['employees','activity','salary','dsa'].includes(current))current='dashboard';app.innerHTML=`<div class="shell"><aside class="sidebar" id="sidebar"><div class="brand">People<b>Desk</b></div><nav class="nav" aria-label="Main navigation">${nav()}</nav><div class="userbox"><b>${esc(me.username)}</b><br>${esc(me.role)}<br><button class="btn small" id="logout">Sign out</button></div></aside><section class="main"><header class="topbar"><div class="inline"><button class="btn mobile-menu" id="menu" aria-label="Open menu" aria-expanded="false">☰</button><strong>${me.role==='ADMIN'?'System administration':hr?'People operations':'Employee workspace'}</strong></div><span class="badge">${esc(me.role)}</span></header><main class="content" id="page"></main></section></div>`;document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{current=b.dataset.page;document.querySelector('#sidebar').classList.remove('open');document.querySelector('#menu').setAttribute('aria-expanded','false');render()});document.querySelector('#menu').onclick=()=>{const open=document.querySelector('#sidebar').classList.toggle('open');document.querySelector('#menu').setAttribute('aria-expanded',String(open))};document.querySelector('#logout').onclick=async()=>{try{await api('/logout',{method:'POST',body:'{}'})}finally{me=null;csrf='';login()}};try{await page()}catch(e){document.querySelector('#page').innerHTML=`<div class="message" role="alert">${esc(e.message)}</div>`}}
