   for(const employees of byDepartment.values())employees.sort((a,b)=>a.id.localeCompare(b.id));
   graphCount.textContent=`${data.employeeCount} employees · ${data.departmentCount} departments · ${data.edgeCount} memberships`;
   const columns=Math.min(3,Math.max(1,departments.length)),groupWidth=340,groupGap=20,rowGap=28,margin=24,employeeWidth=154,employeeHeight=58,employeeStep=72,departmentHeight=58;
