   const departmentNodes=[],employeeNodes=[];
   groups.forEach(group=>{const x=margin+group.column*(groupWidth+groupGap),top=rowTops[group.row],departmentX=x+groupWidth/2;departmentNodes.push({department:group.department,x:departmentX,y:top});group.employees.forEach((employee,index)=>{const col=index%2,row=Math.floor(index/2),employeeX=x+(col===0?86:254),employeeY=top+88+row*employeeStep;employeeNodes.push({employee,x:employeeX,y:employeeY,departmentX,departmentY:top+departmentHeight})})});
   const edges=employeeNodes.map(({employee,x,y,departmentX,departmentY})=>`<line class="connection-graph-edge" x1="${departmentX}" y1="${departmentY}" x2="${x}" y2="${y-employeeHeight/2}"/>`).join('');
   const departmentsSvg=departmentNodes.map(({department,x,y})=>`<g class="connection-graph-node connection-graph-department-node"><rect x="${x-95}" y="${y}" width="190" height="${departmentHeight}" rx="10"/><text class="connection-graph-department-name" x="${x}" y="${y+35}" text-anchor="middle">${esc(department)}</text></g>`).join('');
   const employeesSvg=employeeNodes.map(({employee,x,y})=>{const fit=employee.name.length>18?'textLength="132" lengthAdjust="spacingAndGlyphs"':'';return `<g class="connection-graph-node connection-graph-employee-node"><rect x="${x-employeeWidth/2}" y="${y}" width="${employeeWidth}" height="${employeeHeight}" rx="9"/><text class="connection-graph-id" x="${x}" y="${y+22}" text-anchor="middle">${esc(employee.id)}</text><text class="connection-graph-name" x="${x}" y="${y+43}" text-anchor="middle" ${fit}>${esc(employee.name)}</text></g>`}).join('');
