   const matrixRows=data.membershipMatrix||[];matrixDisplay.innerHTML=`<div class="connection-matrix-viewport" role="region" aria-label="Scrollable employee to department membership matrix"><table class="connection-graph-matrix connection-membership-matrix"><thead><tr><th scope="col">Employee</th>${departments.map(department=>`<th scope="col">${esc(department)}</th>`).join('')}</tr></thead><tbody>${matrixRows.map(row=>`<tr><th scope="row"><span class="connection-matrix-employee-id">${esc(row.employeeId)}</span><span class="connection-matrix-employee-name">${esc(row.employeeName)}</span></th>${row.values.map(value=>`<td>${value}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
   edgeListDisplay.innerHTML=`<div class="table-wrap"><table><thead><tr><th>Employee ID</th><th>Department</th><th>Edge</th></tr></thead><tbody>${data.edgeList.map(edge=>`<tr><td>${esc(edge.employeeId)}</td><td>${esc(edge.department)}</td><td>${esc(edge.employeeId)} → ${esc(edge.department)}</td></tr>`).join('')}</tbody></table></div>`;
   const selectedStart=graphBfsStart.value;graphBfsStart.innerHTML='<option value="">Choose a vertex</option>'+data.vertices.map(vertex=>{const employee=people[vertex],label=employee?`${employee.id} · ${employee.name}`:`Department · ${vertex}`;return `<option value="${esc(vertex)}">${esc(label)}</option>`}).join('');if(data.vertices.includes(selectedStart))graphBfsStart.value=selectedStart;
