function salaryPage(el){el.innerHTML=heading('Salary Calculator','Estimate monthly and annual pay from the figures you enter.')+`<div class="card"><p class="sub">This estimate does not calculate tax or statutory payroll deductions and does not save values to an employee record.</p><form id="salary-form" class="grid split">${[['basic','Basic monthly salary'],['allowances','Allowances'],['other','Overtime / other earnings'],['bonus','Optional bonus'],['deductions','Deductions']].map(([id,label])=>`<div class="field"><label for="salary-${id}">${label} (₹)</label><input id="salary-${id}" name="${id}" type="number" min="0" max="9000000000000" step="0.01" value="0" inputmode="decimal" required></div>`).join('')}<div class="inline"><button type="reset" class="btn">Clear</button></div></form><div id="salary-result" class="grid stats" aria-live="polite"></div></div>`;const form=el.querySelector('#salary-form'),result=el.querySelector('#salary-result'),fmt=new Intl.NumberFormat('en-IN',{maximumFractionDigits:0}),money=c=>{const negative=c<0n,amount=negative?-c:c;return `${negative?'-':''}₹${fmt.format(Number(amount/100n))}.${String(amount%100n).padStart(2,'0')}`};function calc(){try{let values={};for(const input of form.querySelectorAll('input')){if(!/^(?:\d+)(?:\.\d{1,2})?$/.test(input.value))throw Error('Enter non-negative amounts with at most two decimal places.');let [rupees,paise='']=input.value.split('.');let cents=BigInt(rupees)*100n+BigInt((paise+'00').slice(0,2));if(cents>9000000000000000n)throw Error('Amount exceeds the supported limit.');values[input.name]=cents}let gross=values.basic+values.allowances+values.other+values.bonus,ded=values.deductions,net=gross-ded,annualGross=gross*12n,annualNet=net*12n;result.innerHTML=`<div class="card"><div class="stat-label">Gross monthly</div><div class="stat-value">${money(gross)}</div></div><div class="card"><div class="stat-label">Total deductions</div><div class="stat-value">${money(ded)}</div></div><div class="card"><div class="stat-label">Net monthly</div><div class="stat-value">${money(net)}</div></div><div class="card"><div class="stat-label">Estimated annual gross</div><div class="stat-value">${money(annualGross)}</div></div><div class="card"><div class="stat-label">Estimated annual net</div><div class="stat-value">${money(annualNet)}</div></div><p class="sub">Gross = basic + allowances + overtime/other earnings + bonus. Net = gross − deductions. Annual gross and net estimates each multiply the corresponding monthly figure by 12.</p>`}catch(e){result.innerHTML=`<div class="message">${esc(e.message)}</div>`}}form.addEventListener('input',calc);form.addEventListener('reset',()=>setTimeout(calc));calc()}async function reloadEmployees(resetPage=false){const version=++employeeQueryVersion;try{const params=new URLSearchParams({sortBy:sortKey,direction:sortDirection,search:document.querySelector('#search')?.value.trim()||'',status:document.querySelector('#status')?.value||'',searchAlgorithm});const result=await api(`/employees?${params}`);if(version!==employeeQueryVersion)return;employees=result;drawEmployees(resetPage)}catch(error){if(version===employeeQueryVersion)toast(error.message,true)}}function drawEmployees(resetPage=false){if(resetPage)employeePage=1;const q=document.querySelector('#search').value.trim(),status=document.querySelector('#status').value,sorted=employees;document.querySelector('#sort-field').value=sortKey;document.querySelector('#sort-order').value=sortDirection;const pages=Math.max(1,Math.ceil(sorted.length/employeePageSize));employeePage=Math.min(employeePage,pages);const visible=sorted.slice((employeePage-1)*employeePageSize,employeePage*employeePageSize);const table=visible.length?`<div class="table-wrap" role="region" aria-label="Employee records" tabindex="0"><table><thead><tr><th>Employee</th><th>Department</th><th>Designation</th><th>Annual salary</th><th>Joining date</th><th>Status</th><th>Actions</th></tr></thead><tbody>${visible.map(e=>`<tr><td><b>${esc(e.name)}</b><br><small>${esc(e.id)} · ${esc(e.email)}</small></td><td>${esc(e.department)}</td><td>${esc(e.designation)}</td><td>₹${Number(e.salary).toLocaleString('en-IN')}</td><td>${esc(e.joiningDate)}</td><td><span class="badge ${esc(e.status)}">${esc(e.status)}</span></td><td class="row-actions"><button class="btn small" data-view="${esc(e.id)}" aria-label="View ${esc(e.name)}">View</button> <button class="btn small" data-edit="${esc(e.id)}" aria-label="Edit ${esc(e.name)}">Edit</button> <button class="btn small danger" data-delete="${esc(e.id)}" aria-label="Delete ${esc(e.name)}">Delete</button></td></tr>`).join('')}</tbody></table></div>`:`<div class="empty">${q||status?'No employees match these filters.':'No employee records are available.'}${q||status?'<br><button class="btn small" id="clear-filters">Clear search and filters</button>':'<br><button class="btn small primary" id="empty-add">Add an employee</button>'}</div>`;document.querySelector('#table').innerHTML=table+`<div class="pagination"><span>${sorted.length?`Showing ${(employeePage-1)*employeePageSize+1}–${Math.min(employeePage*employeePageSize,sorted.length)} of ${sorted.length}`:'0 employees'}</span><div class="inline"><button class="btn small" id="page-previous" ${employeePage<=1?'disabled':''}>Previous</button><span>Page ${employeePage} of ${pages}</span><button class="btn small" id="page-next" ${employeePage>=pages?'disabled':''}>Next</button></div></div>`;document.querySelector('#clear-filters')?.addEventListener('click',()=>{document.querySelector('#search').value='';document.querySelector('#status').value='';reloadEmployees(true)});document.querySelector('#empty-add')?.addEventListener('click',()=>employeeForm());document.querySelector('#page-previous').onclick=()=>{employeePage--;drawEmployees()};document.querySelector('#page-next').onclick=()=>{employeePage++;drawEmployees()};document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>employeeDetails(employees.find(e=>e.id===b.dataset.view)));document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>employeeForm(employees.find(e=>e.id===b.dataset.edit)));document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=async()=>{const e=employees.find(x=>x.id===b.dataset.delete);if(!(await confirmAction('Delete employee',`Delete ${e.name} (${e.id})? This removes the employee record and may be blocked if it has linked accounts or request history.`)))return;b.disabled=true;try{await api(`/employees/${encodeURIComponent(e.id)}`,{method:'DELETE'});toast('Employee deleted successfully.');await page()}catch(error){toast(error.message,true)}finally{b.disabled=false}})}function modal(content){const opener=document.activeElement,n=document.createElement('div');n.className='modal';n.innerHTML=`<section class="modal-card">${content}</section>`;const panel=n.querySelector('.modal-card'),title=panel.querySelector('h2');panel.setAttribute('role','dialog');panel.setAttribute('aria-modal','true');if(title){title.id='dialog-title';panel.setAttribute('aria-labelledby','dialog-title')}n.closeDialog=()=>{if(!n.isConnected)return;n.onclose?.(false);n.remove();opener?.focus()};n.onclick=e=>{if(e.target===n)n.closeDialog()};n.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();n.closeDialog();return}if(e.key==='Tab'){const items=[...panel.querySelectorAll('button,input,select,textarea,[href],[tabindex]:not([tabindex="-1"])')].filter(x=>!x.disabled);if(!items.length)return;const first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});document.body.append(n);panel.querySelector('button,input,select,textarea')?.focus();return n}function confirmAction(title,message,confirmLabel='Confirm'){return new Promise(resolve=>{const dialog=modal(`<h2>${esc(title)}</h2><p>${esc(message)}</p><div class="inline dialog-actions"><button type="button" class="btn" data-cancel>Cancel</button><button type="button" class="btn danger" data-confirm>${esc(confirmLabel)}</button></div>`);let settled=false;const finish=value=>{if(settled)return;settled=true;dialog.onclose=null;dialog.remove();resolve(value)};dialog.onclose=()=>finish(false);dialog.querySelector('[data-cancel]').onclick=()=>{dialog.onclose=null;dialog.closeDialog();finish(false)};dialog.querySelector('[data-confirm]').onclick=()=>{dialog.onclose=null;dialog.closeDialog();finish(true)}})}async function employeeDetails(e){const m=modal(`<h2>Employee details</h2><div id="detail-content" class="grid split"><p class="sub">Loading employee details…</p></div><button class="btn" id="close">Close</button>`);m.querySelector("#close").onclick=()=>m.closeDialog();try{const record=await api(`/employees/${encodeURIComponent(e.id)}`);if(!m.isConnected)return;m.querySelector("#detail-content").innerHTML=[["Employee ID",record.id],["Name",record.name],["Department",record.department],["Designation",record.designation],["Email",record.email],["Phone",record.phone],["Joining date",record.joiningDate],["Annual salary (₹)",record.salary],["Status",record.status]].map(([k,v])=>`<p><small class="sub">${k}</small><br><b>${esc(v)}</b></p>`).join("")}catch(error){if(!m.isConnected)return;m.querySelector("#detail-content").innerHTML=`<div class="message">${esc(error.message)}</div>`}}function employeeForm(e){let m=modal(`<h2>${e?'Edit':'Add'} employee</h2><form id="empform">${[['id','Employee ID'],['name','Full name'],['department','Department'],['designation','Designation'],['email','Email'],['phone','Phone'],['joiningDate','Joining date'],['salary','Annual salary (₹)'],['status','Status']].map(([k,l])=>`<div class="field"><label for="emp-${k}">${l}</label>${k==='status'?`<select id="emp-${k}" name="${k}"><option>ACTIVE</option><option>ON_LEAVE</option><option>INACTIVE</option></select>`:`<input id="emp-${k}" name="${k}" ${k==='joiningDate'?'type="date"':k==='email'?'type="email"':k==='salary'?'type="number" min="0" step="0.01"':''} required maxlength="${k==='name'?100:80}" ${e&&k==='id'?'readonly':''}>`}</div>`).join('')}<div class="inline"><button type="button" class="btn" id="cancel">Cancel</button><button class="btn primary">Save employee</button></div></form>`);if(e)Object.entries(e).forEach(([k,v])=>{let x=m.querySelector(`[name=${k}]`);if(x)x.value=v});m.querySelector('#cancel').onclick=()=>m.closeDialog();m.querySelector('form').onsubmit=async ev=>{ev.preventDefault();let data=Object.fromEntries(new FormData(ev.target));try{await api(e?`/employees/${encodeURIComponent(e.id)}`:'/employees',{method:e?'PUT':'POST',body:JSON.stringify(data)});m.closeDialog();toast(e?'Employee updated successfully.':'Employee added successfully.');await page()}catch(x){formError(m.querySelector('form'),x.message)}}}
function requestRow(x,review=false,employeeName='',isOldestPending=false){return `<div class="list-item"><div><b>${esc(x.type)}</b> <span class="badge ${esc(x.status)}">${esc(x.status)}</span><div class="sub">Request ID: <span class="mono">${esc(x.id)}</span></div>${x.type.toLowerCase()==='leave'?`<div class="sub"><b>Employee:</b> ${employeeName?`${esc(employeeName)} · `:''}${esc(x.employeeId)}</div><div class="sub"><b>Leave type:</b> Leave · <b>Dates:</b> ${esc(x.leaveFrom)} → ${esc(x.leaveTo)}</div><div class="sub"><b>Reason:</b> ${esc(x.details)}</div>`:`<div class="sub">${esc(x.details)}</div><div class="sub">${employeeName?`${esc(employeeName)} · `:''}${esc(x.employeeId)}</div>`}<small>Submitted ${new Date(x.createdAt).toLocaleString()}</small></div>${review&&x.status==='PENDING'&&isOldestPending?`<div class="inline"><button class="btn small" data-id="${esc(x.id)}" data-decision="APPROVED">Approve</button><button class="btn small danger" data-id="${esc(x.id)}" data-decision="REJECTED">Reject</button></div>`:review&&x.status==='PENDING'?'<span class="sub">Waiting for earlier requests</span>':''}</div>`}async function decideRegistration(id,decision,button){if(button?.disabled)return;if(decision==='REJECTED'&&!(await confirmAction('Reject registration',`Reject the employee registration request ${id}? The applicant will not be able to sign in.`,'Reject registration')))return;if(button)button.disabled=true;try{await api('/registration-requests/decision',{method:'POST',body:JSON.stringify({id,decision})});toast(`Registration ${decision==='APPROVED'?'approved':'rejected'} successfully.`);await page()}catch(error){toast(error.message,true)}finally{if(button?.isConnected)button.disabled=false}}async function decide(id,decision,button){if(button?.disabled)return;if(decision==='REJECTED'&&!(await confirmAction('Reject employee request',`Reject this employee request (${id})? The requester will see it marked as rejected.`,'Reject request')))return;if(button)button.disabled=true;try{await api('/requests/decision',{method:'POST',body:JSON.stringify({id,decision})});toast(`Request ${decision==='APPROVED'?'approved':'rejected'} successfully.`);await page()}catch(error){toast(error.message,true)}finally{if(button?.isConnected)button.disabled=false}}function requestForm(){const m=modal(`<h2>New request</h2><form><div class="field"><label for="request-type">Request type</label><select id="request-type" name="type"><option>Leave</option><option>Profile update</option><option>General</option></select></div><div class="grid split" id="leave-date-range"><div class="field"><label for="leave-from">Leave From</label><input id="leave-from" name="leaveFrom" type="date"></div><div class="field"><label for="leave-to">Leave To</label><input id="leave-to" name="leaveTo" type="date"></div></div><div class="field"><label for="request-details">Details</label><textarea id="request-details" name="details" required maxlength="2000" rows="5"></textarea></div><div class="inline"><button type="button" class="btn" id="cancel">Cancel</button><button class="btn primary">Submit request</button></div></form>`),form=m.querySelector('form'),type=form.querySelector('#request-type'),from=form.querySelector('#leave-from'),to=form.querySelector('#leave-to'),range=form.querySelector('#leave-date-range');function updateLeaveFields(){const required=type.value==='Leave';range.hidden=!required;from.required=required;to.required=required;if(!required){from.value='';to.value='';to.removeAttribute('min')}else if(from.value){to.min=from.value}}type.addEventListener('change',updateLeaveFields);from.addEventListener('input',()=>{if(from.value){to.min=from.value;if(to.value&&to.value<from.value)setFieldError(to,'Leave To cannot be earlier than Leave From.')}});to.addEventListener('change',()=>{if(from.value&&to.value<from.value)setFieldError(to,'Leave To cannot be earlier than Leave From.')});updateLeaveFields();m.querySelector('#cancel').onclick=()=>m.closeDialog();form.onsubmit=async e=>{e.preventDefault();if(type.value==='Leave'&&to.value<from.value){setFieldError(to,'Leave To cannot be earlier than Leave From.');return}const data=Object.fromEntries(new FormData(form));if(type.value!=='Leave'){delete data.leaveFrom;delete data.leaveTo}try{await api('/requests',{method:'POST',body:JSON.stringify(data)});m.closeDialog();toast('Request submitted successfully.');await page()}catch(x){formError(form,x.message)}}}
document.addEventListener('keydown',e=>{if(e.key==='Escape'){const sidebar=document.querySelector('#sidebar'),menu=document.querySelector('#menu');if(sidebar?.classList.contains('open')){sidebar.classList.remove('open');menu?.setAttribute('aria-expanded','false')}}});
boot();
async function activityStackPage(el){
 el.innerHTML=heading('Activity Stack','Recent employee and application activities displayed using the Stack data structure (LIFO).')+`<section class="card activity-stack-demo"><div id="activity-stack-display" class="activity-stack-scroll" aria-label="Activity stack visualization" tabindex="0"></div></section>`;
 const display=el.querySelector('#activity-stack-display');
 try{
  const stack=await api('/activity/stack');
  const activities=Array.isArray(stack.activities)?stack.activities:[];
  display.innerHTML=activities.length?`<div class="activity-stack-edge">TOP</div>${activities.map((item,index)=>`<article class="activity-stack-node"><b>${esc(item.action)}</b><span>${esc(item.target||'')}</span><small>Account: ${esc(item.actor||'Unknown')} · ${Number.isNaN(Date.parse(item.at))?'':new Date(item.at).toLocaleString()}</small></article>${index<activities.length-1?'<div class="activity-stack-link" aria-hidden="true">↓</div>':''}`).join('')}<div class="activity-stack-edge">BOTTOM</div>`:`<div class="activity-stack-empty"><b>TOP</b><span>No activities have been recorded in this server session yet.</span><b>BOTTOM</b></div>`;
 }catch(error){display.innerHTML=`<div class="activity-stack-empty"><b>Activity Stack unavailable</b><span>${esc(error.message||'Activities could not be loaded.')}</span></div>`}
}


